#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/node/tasks/upgrade-npm.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Upgrade npm"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

import os
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  # Check if npm is installed before attempting to update
  if not shutil.which("npm"):
    sys.exit(0)

  # Configure NPM global settings
  helpers.print_header("Configuring npmrc ...")
  run("npm", "config", "--global", "set", "fund=false")

  # Upgrade global npm packages
  helpers.print_subheader("Upgrading global npm packages ...")
  run("npm", "upgrade", "--global")


if __name__ == "__main__":
  main()
